def process(clean_precip_data):
    df = clean_precip_data[clean_precip_data['Year'].isin([2020, 2021, 2022, 2023])].copy()
    return df.sort_values('Year').reset_index(drop=True)

def process(filter_precip_2020_2023):
    df = filter_precip_2020_2023.copy()
    month_cols = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']
    month_map = {m: i+1 for i, m in enumerate(month_cols)}

    melted = df[['Year'] + month_cols].melt(id_vars=['Year'], var_name='Month_Name', value_name='Precipitation')
    melted['Month'] = melted['Month_Name'].map(month_map)
    melted = melted[['Year', 'Month', 'Precipitation']].dropna()
    melted['Precipitation'] = pd.to_numeric(melted['Precipitation'], errors='coerce')
    melted = melted.dropna()

    return melted.sort_values(['Year', 'Month']).reset_index(drop=True)

def process(fresh_water_exceedance):
    df = fresh_water_exceedance.copy()

    for month in range(1, 13):
        month_data = df[df['Month'] == month]['Exceedance_Rate']
        if len(month_data) > 0:
            median_val = month_data.median()
            df.loc[(df['Month'] == month) & (df['Exceedance_Rate'].isna()), 'Exceedance_Rate'] = median_val

    return df.sort_values(['Year', 'Month']).reset_index(drop=True)

def process(monthly_precip_unpivot):
    df = monthly_precip_unpivot.copy()

    for month in range(1, 13):
        month_data = df[df['Month'] == month]['Precipitation']
        if len(month_data) > 0:
            median_val = month_data.median()
            df.loc[(df['Month'] == month) & (df['Precipitation'].isna()), 'Precipitation'] = median_val

    return df.sort_values(['Year', 'Month']).reset_index(drop=True)

def process(impute_exceedance_medians, impute_precip_medians):
    exceedance = impute_exceedance_medians.copy()
    precip = impute_precip_medians.copy()

    merged = exceedance.merge(precip, on=['Year', 'Month'], how='inner')
    return merged.sort_values(['Year', 'Month']).reset_index(drop=True)

